const MY=window.CAREER_IMPORT;
const mySections=[['overview','Overview','grid'],['skills','Skills library','code'],['mcps','MCPs & servers','plug'],['systems','My AI systems','layers'],['resources','Resource board','globe']];
const mySidebar=sidebar;sidebar=function(){return mySidebar().replace('</nav>','<details open class="nav-level-one my-navigation"><summary>'+svgIcon('layers')+'<span>My Systems & Resources</span>'+svgIcon('chevron')+'</summary><div>'+mySections.map(([r,t,i])=>navLeaf('my-library/'+r,t,i)).join('')+'</div></details></nav>');};
function myBlocks(blocks){return (blocks||[]).map(b=>{if(b.t==='table')return '<pre>'+esc(JSON.stringify(b.rows||b,null,2))+'</pre>';const tag={h1:'h1',h2:'h2',h3:'h3',bullet:'p',li:'p',quote:'blockquote'}[b.t]||'p';return '<'+tag+'>'+((b.t==='bullet'||b.t==='li')?'• ':'')+esc(b.x||'')+'</'+tag+'>';}).join('');}
function myPreview(title,html){let dialog=document.getElementById('my-preview');if(dialog)dialog.remove();dialog=document.createElement('dialog');dialog.id='my-preview';dialog.className='my-preview';dialog.innerHTML='<header><div><small>IN-WORKSPACE PREVIEW</small><h2>'+esc(title)+'</h2></div><button aria-label="Close preview">'+svgIcon('close')+'</button></header><div class="my-preview-body">'+html+'</div>';document.body.append(dialog);dialog.querySelector('header button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
function myAsset(rel,title){const asset=MY.assets[rel];if(!asset){myPreview(title,'<div class="my-empty"><h3>Source file unavailable</h3><p>The original hub lists this file, but it was not present at its referenced path. Its catalogue record has been preserved.</p><code>'+esc(rel)+'</code></div>');return;}
 if(/\.html?$/i.test(rel)){myPreview(title,'<iframe title="System document preview" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe>');document.querySelector('#my-preview iframe').srcdoc=asset.text;return;}
 const doc=MY.docs.find(d=>d.path===rel);if(doc){myPreview(title,'<article class="my-document">'+myBlocks(doc.blocks)+'</article>');return;}
 if(asset.text!==undefined){myPreview(title,'<pre class="my-code">'+esc(asset.text)+'</pre>');return;}
 myPreview(title,'<div class="my-empty"><h3>Original file is included</h3><p>This binary format cannot be rendered inline. Download a verified copy to open in its native application.</p><button id="my-download">Download original</button></div>');document.getElementById('my-download').onclick=()=>{const blob=new Blob([Uint8Array.from(atob(asset.base64),c=>c.charCodeAt(0))]);const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=rel.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};}
function myList(section){if(section==='skills')return MY.skills.skills.map((x,i)=>({id:i,title:x.n,category:x.coll||'Skills',description:x.d,kind:'Skill',original:x}));
if(section==='mcps')return MY.skills.mcps.map((x,i)=>({id:i,title:x.n,category:x.cat,description:x.d,kind:'MCP server',original:x}));
if(section==='systems')return MY.systems.map((x,i)=>({id:i,title:x.system,category:'System blueprints',description:x.subtitle,kind:x.agents+' agents · '+x.departments+' departments',original:x}));
if(section==='agents')return MY.agents.map((x,i)=>({id:i,title:x.name,category:x.sys,description:x.role,kind:x.dept,original:x}));
if(section==='resources')return MY.resources.flatMap(c=>c.items.map(x=>({title:x.n,category:c.cat,description:x.d,kind:({ok:'Approved',star:'Favourite',warn:'Review notes',no:'Not selected',new:'New'})[x.s]||x.s,original:x}))).map((x,i)=>({...x,id:i}));
if(section==='documents')return MY.docs.map((x,i)=>({id:i,title:x.title,category:x.section,description:x.path,kind:'Document preview',original:x}));return [];}
function myDetail(section,id){const item=myList(section).find(x=>String(x.id)===String(id));if(!item)return;const x=item.original;
 if(section==='documents'){myAsset(x.path,x.title);return;}
 let html='<article class="my-document"><div class="my-kicker">'+esc(item.category)+'</div><h1>'+esc(item.title)+'</h1><p>'+esc(item.description||'')+'</p>';
 for(const [k,v] of Object.entries(x)){if(['n','name','system','title','d','subtitle','p','file','map'].includes(k)||v==null)continue;html+='<h3>'+esc(({e:'File type',s:section==='resources'?'Original status':'Recorded file size',coll:'Collection',prov:'Provenance',sess:'Session',cat:'Category',tr:'Transport',use:'Use case',r:'Your remark',u:'Source',agents:'Agents',departments:'Departments',accent:'System colour'})[k]||k)+'</h3><p>'+esc(typeof v==='object'?JSON.stringify(v,null,2):String(v))+'</p>';}
 if(x.p)html+='<button data-my-file="'+esc('11 Resources/'+x.p)+'">Preview source file</button>';
 if(x.file)html+='<div class="my-actions"><button data-my-file="'+esc(x.file)+'">Open blueprint</button>'+(x.map?'<button data-my-file="'+esc(x.map)+'">Open system map</button>':'')+'</div>';
 if(x.u&&/^https?:\/\//i.test(x.u))html+='<a class="my-external" href="'+esc(x.u)+'" target="_blank" rel="noopener noreferrer">Open original resource ↗</a>';
 html+='</article>';myPreview(item.title,html);document.querySelectorAll('[data-my-file]').forEach(b=>b.onclick=()=>myAsset(b.dataset.myFile,item.title));}
function myPage(section='overview'){const known=mySections.find(x=>x[0]===section);if(!known)section='overview';
 const target=document.querySelector('#main');target.innerHTML='<section class="my-library"><div class="my-kicker">AHMED EL GENDY / PRIVATE COLLECTION</div><div class="my-title"><div><h1>'+(known?.[1]||'My Systems & Resources')+'</h1><p>Your authored systems and curated resources, together in one place.</p></div><span class="my-badge">Imported from your hub</span></div><nav class="my-tabs">'+mySections.map(([r,t,i])=>'<a '+(r===section?'aria-current="page"':'')+' href="#/my-library/'+r+'">'+svgIcon(i)+t+'</a>').join('')+'</nav><div id="my-content"></div></section>';
 const content=document.getElementById('my-content');
 if(section==='overview'){content.innerHTML='<div class="my-stats">'+[['skills',160,'Skills'],['mcps',14,'MCPs'],['systems',12,'Systems'],['resources',MY.resources.reduce((n,c)=>n+c.items.length,0),'Resources']].map(([r,n,t])=>'<a href="#/my-library/'+r+'"><strong>'+n+'</strong><span>'+t+'</span>'+svgIcon('arrow')+'</a>').join('')+'</div><div class="my-feature"><div><div class="my-kicker">BUILT BY YOU</div><h2>The operating systems<br>behind the ideas.</h2><p>Explore your blueprints, departments, agent roles and original skill files. Your original notes and source categories are preserved.</p><a href="#/my-library/systems">Explore your systems →</a></div><div class="my-orbit">'+svgIcon('layers')+'<span>Systems</span><span>Skills</span><span>Resources</span></div></div><h2>Resource collections</h2><div class="my-grid">'+MY.resources.map(c=>'<a class="my-card" href="#/my-library/resources" data-my-category="'+esc(c.cat)+'">'+svgIcon('folder')+'<h3>'+esc(c.cat)+'</h3><p>'+c.items.length+' curated records</p></a>').join('')+'</div>';document.querySelectorAll('[data-my-category]').forEach(a=>a.onclick=()=>{window.myInitialCategory=a.dataset.myCategory;});return;}
 const records=myList(section),cats=[...new Set(records.map(x=>x.category))];content.innerHTML='<div class="my-toolbar"><label>'+svgIcon('search')+'<input id="my-search" placeholder="Search '+esc(known[1].toLowerCase())+'" aria-label="Search imported collection"></label><select id="my-category" aria-label="Filter collection category"><option value="">All categories</option>'+cats.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><span id="my-count"></span></div><div id="my-results" class="my-grid"></div>';
 const paint=()=>{const q=document.getElementById('my-search').value.toLowerCase(),cat=document.getElementById('my-category').value;const found=records.filter(x=>(!cat||x.category===cat)&&JSON.stringify(x).toLowerCase().includes(q));document.getElementById('my-count').textContent=found.length+' / '+records.length;document.getElementById('my-results').innerHTML=found.map(x=>'<button class="my-card" data-my-item="'+x.id+'">'+svgIcon(known[2])+'<small>'+esc(x.category)+'</small><h3>'+esc(x.title)+'</h3><p>'+esc(x.description||'')+'</p><footer><span>'+esc(x.kind||'')+'</span>'+svgIcon('arrow')+'</footer></button>').join('')||'<div class="my-empty">No matching records. Try another search or category.</div>';document.querySelectorAll('[data-my-item]').forEach(b=>b.onclick=()=>myDetail(section,b.dataset.myItem));};
 if(window.myInitialCategory&&section==='resources'){document.getElementById('my-category').value=window.myInitialCategory;window.myInitialCategory=null;}document.getElementById('my-search').oninput=paint;document.getElementById('my-category').onchange=paint;paint();}
const myPriorRender=render;render=function(){const parts=location.hash.slice(2).split('/');if(parts[0]!=='my-library')return myPriorRender();terminalCancel++;myPage(parts[1]);document.title=B.name+' — My Systems & Resources';document.body.dataset.page='my-library';document.body.classList.remove('catalogue-nav-open');document.querySelectorAll('.universal-sidebar a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));};
